langs = ["en", "es", "it", "zh-Hans"]
def esc(v): return v.replace('"', '\\"')
for i, lang in enumerate(langs, start=1):
    out = ["/* SnapLens — gerado por Tools/translations.py. Chave = texto em pt-BR. */", ""]
    for row in T:
        key = row[0]; val = row[i]
        # chaves já vêm com \" e \n escapados como no código Swift; valores precisam de escape de aspas
        out.append(f'"{key}" = "{esc(val) if chr(92)+chr(34) not in val else val}";')
    d = f"Sources/SnapLens/Resources/{lang}.lproj"; os.makedirs(d, exist_ok=True)
    open(f"{d}/Localizable.strings", "w").write("\n".join(out) + "\n")
print(f"{len(T)} chaves × {len(langs)} idiomas")
